    echo "\n=========================================================================\n";
    echo "   STEP 3: POST-SYNC PRODUCTION DATABASE AUDIT & VERIFICATION           \n";
    echo "=========================================================================\n";

    $postSyncCounts = [];
    foreach ($auditTables as $tbl) {
        $postSyncCounts[$tbl] = (int)$db->query("SELECT COUNT(*) FROM `$tbl`")->fetchColumn();
        echo sprintf("  [POST-SYNC] %-29s : %d rows (added %d rows)\n", $tbl, $postSyncCounts[$tbl], $postSyncCounts[$tbl] - ($preSyncCounts[$tbl] ?? 0));
    }

    // Verify duplicate check on students table
    $dupCheck = (int)$db->query("SELECT COUNT(id) - COUNT(DISTINCT id) FROM students")->fetchColumn();
    $admDupCheck = (int)$db->query("SELECT COUNT(admission_no) - COUNT(DISTINCT admission_no) FROM students WHERE admission_no IS NOT NULL AND admission_no != ''")->fetchColumn();

    echo "\n  [VERIFICATION] Student ID Duplicates    : " . ($dupCheck === 0 ? "0 (PASSED)" : "$dupCheck (WARNING)") . "\n";
    echo "  [VERIFICATION] Admission No Duplicates  : " . ($admDupCheck === 0 ? "0 (PASSED)" : "$admDupCheck (WARNING)") . "\n";

    echo "\n=========================================================================\n";
    echo "🎉 PRODUCTION SYNCHRONIZATION COMPLETE!\n";
    echo "=========================================================================\n";
    echo "</pre>";

    $finalStudentCount = $postSyncCounts['students'];

    if ($finalStudentCount >= 1052) {
        echo "<div class=\"alert alert-success mt-3\">";
        echo "<h4>✅ SUCCESS: Live Database Synchronized to " . $finalStudentCount . " Active Students!</h4>";
        echo "<p class=\"mb-0\">Backup Created: <strong>" . $backupFileName . "</strong> | Fees, Ledgers, Marks & Attendance fully active on LIVE!</p>";
        echo "</div>";
    } else {
        echo "<div class=\"alert alert-warning mt-3\">";
        echo "<h4>⚠️ Synchronization Warning: Live count is " . $finalStudentCount . " students.</h4>";
        echo "</div>";
    }

    echo "<div class=\"d-flex gap-2 mt-3\">";
    echo "<a href=\"templates/student_profile_report.php\" target=\"_blank\" class=\"btn btn-primary btn-lg\">View Profile Reports</a>";
    echo "<a href=\"modules/students/list.php\" class=\"btn btn-success btn-lg\">Go to Students List</a>";
    echo "<a href=\"dashboard.php\" class=\"btn btn-light btn-lg\">Dashboard</a>";
    echo "</div>";

} catch (Exception $e) {
    echo "</pre>";
    echo "<div class=\"alert alert-danger mt-3\">❌ Error during synchronization: " . htmlspecialchars($e->getMessage()) . "</div>";
